TLM.f("Sancti/06-26",{"officium":"Ss. Joannis et Pauli Martyrum","rule":["vide C3;","Gloria"],"fallback":"Commune/C3","from":{"Tractus":"Commune/C3"},"sections":{"Introitus":[{"k":"ref","la":"Ps 33:20-21"},{"k":"text","la":"Multæ tribulatiónes justórum, et de his ómnibus liberávit eos Dóminus: Dóminus custódit ómnia ossa eórum: unum ex his non conterétur."},{"k":"ref","la":"Ps 33:2"},{"k":"text","la":"Benedícam Dóminum in omni témpore: semper laus ejus in ore meo."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Multæ tribulatiónes justórum, et de his ómnibus liberávit eos Dóminus: Dóminus custódit ómnia ossa eórum: unum ex his non conterétur."}],"Oratio":[{"k":"text","la":"Quǽsumus, omnípotens Deus: ut nos gemináta lætítia hodiérnæ festivitátis excípiat, quæ de beatórum Joánnis et Pauli glorificatióne procédit; quos eadem fides et pássio vere fecit esse germános."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Eccli 44:10-15"},{"k":"text","la":"Hi viri misericórdiæ sunt, quorum pietátes non defuérunt: cum semine eórum pérmanent bona, heréditas sancta nepótes eórum, et in testaméntis stetit semen eórum: et fílii eórum propter illos usque in ætérnum manent: semen eórum et glória eórum non derelinquétur. Córpora ipsórum in pace sepúlta sunt, et nomen eórum vivit in generatiónem et generatiónem. Sapiéntiam ipsórum narrent pópuli, et laudem eórum núntiet Ecclésia."}],"Graduale":[{"k":"ref","la":"Ps 132:1-2"},{"k":"text","la":"Ecce, quam bonum et quam jucúndum, habitáre fratres in unum!"},{"k":"text","la":"Sicut unguéntum in cápite, quod descéndit in barbam, barbam Aaron. Allelúja, allelúja.","mark":"V"},{"k":"text","la":"Hæc est vera fratérnitas, quæ vicit mundi crímina: Christum secúta est, ínclita tenens regna cœléstia. Allelúja.","mark":"V"}],"Tractus":[{"k":"ref","la":"Exod 15:11"},{"k":"text","la":"Gloriósus Deus in Sanctis suis: mirábilis in majestáte, fáciens prodígia."},{"k":"ref","la":"Exod 15:6"},{"k":"text","la":"Déxtera tua, Dómine, glorificáta est in virtúte: déxtera manus tua confrégit inimícos.","mark":"V"},{"k":"ref","la":"Ps 125:5-6"},{"k":"text","la":"Qui séminant in lácrimis, in gáudio metent."},{"k":"text","la":"Eúntes ibant et flébant, mitténtes sémina sua.","mark":"V"},{"k":"text","la":"Veniéntes autem vénient cum exsultatióne, portántes manípulos suos.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 12:1-8"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Atténdite a ferménto pharisæórum, quod est hypócrisis. Nihil autem opértum est, quod non revelétur: neque abscónditum, quod non sciátur. Quóniam, quæ in ténebris dixístis, in lúmine dicéntur: et quod in aurem locúti estis in cubículis, prædicábitur in tectis. Dico autem vobis amícis meis: Ne terreámini ab his, qui occídunt corpus, et post hæc non habent ámplius quid fáciant. Osténdam autem vobis, quem timeátis: timéte eum, qui postquam occíderit, habet potestátem míttere in gehénnam. Ita dico vobis: hunc timéte. Nonne quinque pásseres véneunt dipóndio, et unus ex illis non est in oblivióne coram Deo? Sed et capílli cápitis vestri omnes numeráti sunt. Nolíte ergo timére: multis passéribus pluris estis vos. Dico autem vobis: Omnis, quicúmque conféssus fúerit me coram homínibus, et Fílius hóminis confitébitur illum coram Angelis Dei."}],"Offertorium":[{"k":"ref","la":"Ps 5:12-13"},{"k":"text","la":"Gloriabúntur in te omnes, qui díligunt nomen tuum: quóniam tu, Dómine, benedíces justo: Dómine, ut scuto bonæ voluntátis tuæ coronásti nos."}],"Secreta":[{"k":"text","la":"Hóstias tibi, Dómine, sanctórum Martyrum tuórum Joánnis et Pauli dicátas méritis, benígnus assúme: et ad perpétuum nobis tríbue proveníre subsídium."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Sap 3:4-6"},{"k":"text","la":"Et si coram homínibus torménta passi sunt, Deus tentávit eos: tamquam aurum in fornáce probávit eos, et quasi holocáusta accépit eos."}],"Postcommunio":[{"k":"text","la":"Súmpsimus, Dómine, sanctórum Martyrum tuórum Joánnis et Pauli sollémnia celebrántes, sacraménta cœléstia: præsta, quǽsumus; ut, quod temporáliter gérimus, ætérnis gáudiis consequámur."},{"k":"macro","name":"Per Dominum"}]},"hr":{"07f3123185ddb723":{"t":"Ps 33, 20-21, Ps 33, 2\n(Ps 33, 20-21) Mnoge jade trpe pravednici, ali će ih od svih izbaviti Gospodin. Gospodin čuva sve kosti njihove, ni jedna se neće skršiti. (Ps 33, 2) Blagoslivljat ću Gospodina u svako doba, na ustima mi je uvijek hvala njegova.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 33, 20-21) Mnoge jade trpe pravednici, ali će ih od svih izbaviti Gospodin. Gospodin čuva sve kosti njihove, ni jedna se neće skršiti.","kn":"(Ps. 33, 20, 21). Mnoge su nevolje pravednih i od svih ih je izbavio Gospodin; Gospodin čuva sve. kosti njihove, nijedna se od njih ne će slomiti. (Ps. 33, 2.) Blagosiljat ću Gospodina u svako doba, svagda je hvala njegova u ustima mojim. Slava Ocu . . . Mnoge . .","knRef":"Kniewald 1942, str. 598–599 (snimka 300) (OCR)"},"43ea6bac1af5cf8f":{"t":"<i>Pomolimo se</i>.\nMolimo, svemogući Bože, da nas zahvati dvostruka radost današnje svetkovine što proizlazi iz proslave blaženih Ivana i Pavla, koje je ista vjera i mučeništvo učinilo da budu doista braća.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo, svemogući Bože, da uživamo dvojaku radost današnje svetkovine, kojom slavimo blažene Ivana i Pavla, što ih je ista vjera i mučeništvo doista učinilo pravom braćom, po G. n.","knRef":"Kniewald 1942, str. 610–611 (snimka 306) (OCR)"},"b3c8783356ef550e":{"t":"Sir 44, 10-15\nČitanje knjige Mudrosti. Ovo su milosrdni ljudi, i djela njihova milosrđa neće nestati. Dobra im djela ostaju s porodom, njihovi potomci sveta su baština, njihov rod ostaje vjeran zavjetima. Radi njih će vječno ostati njihova djeca. Neće nestati ni njihova roda ni njihove slave. Tjelesa su im sahranjena u miru, njihovo će ime živjeti od roda do roda. Neka narodi govore o njihovoj mudrosti, a crkva neka navješćuje njihovu hvalu!","kn":"Čitanje knjige mudrosti (Crkv. 44, 10-15). Ovo su milosrdni muževi i djela njihova milosrđa nijesu nestala. Dobra im djela ostaju s porodom, njihovi potomci su sveta baština i njihov je rod ostao vjeran zavjetima. I radi njih će vječno postojati njihova djeca, ne će nestati njihova roda ni njihove slave. TjeleSa su im sahranjena u miru, njihovo će ime živjeti od roda do roda. Narodi neka propovijedaju njihovu mudrost i zbor neka navješćuju njihovu slavu.","knRef":"Kniewald 1942, str. 610–611 (snimka 306) (OCR)"},"858391bd6b653b4b":{"t":"Ps 132, 1-2\nGle, kako je dobro i ugodno da braća stanuju zajedno! Kao najbolje ulje što teče na bradu Aronovu.\n\nPs 109, 4\n<i>Aleluja</i>, <i>aleluja</i>.\nOvo je pravo bratstvo koje je pobijedilo opačine svijeta, slijedilo je Krista i zadobilo slavno nebesko kraljevstvo. <i>Aleluja</i>.","kn":"(Ps. 132, 1-2). Kako je lijepo i ugodno, kad braća žive zajedno, kao dobro ulje Izlito na glavu, koje se stače na bradu Aronovu.\n\nAleluja, aleluja. To je pravo bratstvo, koje je pobijedilo opačine svijeta, slijedeći Krista, zadobilo je kraljevstvo nebesko, aleluja","knRef":"Kniewald 1942, str. 522–523 (snimka 262) (OCR)"},"fd132778da52f21b":{"t":"Lk 12, 1-8\nSlijedi sveto Evanđelje po Luki. U ono vrijeme reče Isus svojim učenicima: Čuvajte se farizejskog kvasca, to jest licemjerja. Ništa nije sakriveno što se ne bi otkrilo, ni tajno što se ne bi saznalo. Što ste govorili u tajnosti kazat će se na javnosti, a što ste šaptali u uho u sobama propovijedat će se na krovovima. A vama svojim prijateljima kažem: Ne bojte se onih koji ubijaju tijelo, a poslije toga ne mogu više ništa. Kazat ću vam koga se imate bojati: Bojte se onoga koji poslije smrti može baciti u pakao. Da, ponavljam: Njega se bojte! Zar se ne prodaje pet vrabaca za dva novčića? A ni jedan od njih nije zaboravljen kod Boga. A na vašoj su glavi sve vlasi izbrojane. Nemojte se, dakle, bojati, jer vi vrijedite više nego mnogo vrabaca. Kažem vam: Tko god prizna mene pred ljudima, priznat će i njega Sin Čovječji pred Božjim anđelima!","kn":"t Slijedi sveto evanđelje po Luki (12, 1-8). U ono vrijeme reče Isus svojim učenicima: Čuvajte se farizejskoga kvasca, to jest licemjera. Ništa nema sakrivena, što se ne će otkriti, niti tajna, što se ne će saznati. Jer što ste govorili u tajnosti, govorit će se na javi, i što ste na uho’ šaptali u sobama, razglasit će se na krovovima. A kažem vama, svojim prijateljima; Ne iplašite se onih, koji ubijaju tijelo, a poslije toga ne mogu učiniti više ništa. Kazat ču vam, koga se imate bojati: Bojte se onoga, koji kad ubije, može baciti u pakao. Da, kažem vam: Bojte se njega! Zar se ne prodaje pet vrabaca za dva novčića? A nijedan od njih nije zaboravljen pred Bogom. A na vašoj su glavi izbrojene sve vlasi. Nemojte se dakle bojati, jer vi vrijedite više nego mnogo vrabaca. Kažem vam: Svakoga, kojigod mene prizna pred ljudima, priznat će i Sin čovječji pred Božjim anđelima.","knRef":"Kniewald 1942, str. 610–611 (snimka 306) (OCR)"},"f18e3b3e275ba7b6":{"t":"Ps 5, 12-13\nDičit će se tobom svi koji ljube ime tvoje, jer ti blagoslivljaš pravednika, Gospodine, tvoja nas dobrota kao štit brani.","kn":"(Ps. 5, 12, 13). Đičit će se Tobom svi, koji ljube ime Tvoje, jer Ti blagosivaš pravednika i zaklanjaš nas milošću svojom kao štitom. Gospodine.","knRef":"Kniewald 1942, str. 610–611 (snimka 306) (OCR)"},"ba7105f9194be904":{"t":"Milostivo primi, Gospodine, darove tebi prikazane po zaslugama svetih mučenika tvojih Ivana i Pavla i daj da nam budu na neprestanu pomoć.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primi blagostiv. Gospodine, žrtve, što su Ti prinesene radi zasluga svetih Tvojih mučenika Ivana i Pavla 1 podaj, da nam uskoriste za vječnu pomoć, po G. n.","knRef":"Kniewald 1942, str. 610–611 (snimka 306) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vjećni Bože, po Kristu, Gospodinu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i . blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se i naši glasovi združe s njihovima, smjernim ispovijedanjem govoreći:","knRef":"Kniewald 1942, str. 758–759 (snimka 380) (OCR)"},"818b40676ad77c2d":{"t":"Mudr 3, 4 i 5 i 6\nI ako su pred ljudima trpjeli muke, Bog ih je iskušao. Prokušao ih je kao zlato u peći i primio ih je kao žrtve paljenice.","kn":"(Mudr. 3, 4-6). I ako su muke trpjeli pred ljudima. Bog, Ih je kušao; iskušao ih je kao zlato u peći i primio ih kao žrtvu paljenicu.","knRef":"Kniewald 1942, str. 798–799 (snimka 400) (OCR)"},"7df0b8edda34ffe2":{"t":"<i>Pomolimo se</i>.\nPrimili smo, Gospodine, nebeska otajstva slaveći svetkovinu svetih mučenika tvojih Ivana i Pavla. Podaj molimo, da zaslužimo vječnu radost ovim što obavljamo u vremenu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primivši nebeska otajstva o svetkovini Tvojih svetih mučenika Ivana i Pavla, molimo Te, Gospodine, da vječnom radošću dostignemo ono, što sada ovršujemo; po G. n.","knRef":"Kniewald 1942, str. 612–613 (snimka 307) (OCR)"}}});
